const response = $input.first().json;
let parsed;
try {
  const text = response.content[0].text;
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { intent_level: 'null', event: null, slack_confirmation_message: null, alternatives: [] };
}
return [{ json: parsed }];

const parsed = $input.first().json;
const ev = parsed.event;
const payload = JSON.stringify(ev);
const encoded = Buffer.from(payload).toString('base64url');
const base = 'https://n8n.nelson-torres.dev/webhook/calendar-confirm';
const confirmUrl = base + '?action=confirm&data=' + encoded;
const denyUrl = base + '?action=deny&data=' + encoded;
const startDt = ev.start_datetime ? new Date(ev.start_datetime) : null;
const endDt = ev.end_datetime ? new Date(ev.end_datetime) : null;
const fmtOpts = { timeZone: 'America/Los_Angeles', dateStyle: 'medium', timeStyle: 'short' };
const startStr = startDt ? startDt.toLocaleString('en-US', fmtOpts) : 'TBD';
const endStr = endDt ? endDt.toLocaleString('en-US', { timeZone: 'America/Los_Angeles', timeStyle: 'short' }) : '';
const attendees = (ev.attendees || []).join(', ') || 'None';
const lines = [
  '📅 *Calendar Event Draft*',
  '',
  '📌 *' + ev.title + '*',
  '⏰ ' + startStr + (endStr ? ' – ' + endStr : ''),
  '👥 ' + attendees,
  ev.location ? '📍 ' + ev.location : null,
  '📝 ' + (ev.description || 'No description'),
  '',
  '<' + confirmUrl + '|✅ *Confirm — Create Event*>',
  '<' + denyUrl + '|❌ *Deny — Discard*>',
  '',
  '_✦ Iris — Nelson\'s personal AI assistant_'
];
return [{ json: { slackMessage: lines.filter(function(l) { return l !== null; }).join('\n') } }];

